/*
 * iq_table_check.c — cross-language consistency probe for the IQ tables.
 *
 * The table data itself lives in src/iq_tables.zig (generated by
 * scripts/gen_iq_tables.py from llama.cpp's ggml-common.h).  This file holds
 * only *expected values*, not the data: it reads the tables through the
 * extern declarations in iq_tables.h and reports how many entries differ from
 * the upstream anchors.  It is the C-side counterpart of the comptime checks
 * in src/iq_tables.zig, and it is what proves the C kernels are actually
 * reaching the Zig-defined objects rather than some stale copy.
 *
 * Returns the number of mismatches (0 == all tables agree).
 */

#include "iq_tables.h"

#include <stdint.h>
#include <stddef.h>

/* Upstream anchors, restated here on purpose.  A table that drifts in either
 * language trips this check; the duplication is the test, not the source. */
static const uint8_t expect_ksigns[128] = {
    0, 129, 130, 3, 132, 5, 6, 135, 136, 9, 10, 139, 12, 141, 142, 15,
    144, 17, 18, 147, 20, 149, 150, 23, 24, 153, 154, 27, 156, 29, 30, 159,
    160, 33, 34, 163, 36, 165, 166, 39, 40, 169, 170, 43, 172, 45, 46, 175,
    48, 177, 178, 51, 180, 53, 54, 183, 184, 57, 58, 187, 60, 189, 190, 63,
    192, 65, 66, 195, 68, 197, 198, 71, 72, 201, 202, 75, 204, 77, 78, 207,
    80, 209, 210, 83, 212, 85, 86, 215, 216, 89, 90, 219, 92, 221, 222, 95,
    96, 225, 226, 99, 228, 101, 102, 231, 232, 105, 106, 235, 108, 237, 238, 111,
    240, 113, 114, 243, 116, 245, 246, 119, 120, 249, 250, 123, 252, 125, 126, 255
};

static const int8_t expect_iq4nl[16] = {
    -127, -104, -83, -65, -49, -35, -22, -10, 1, 13, 25, 38, 53, 69, 89, 113
};

static const int8_t expect_fp4[16] = {
    0, 1, 2, 3, 4, 6, 8, 12, 0, -1, -2, -3, -4, -6, -8, -12
};

/* Representative grid entries: index 0, index 1, and the last element of each
 * grid.  Enough to catch a shifted/truncated table, cheap enough to keep here. */
static const uint64_t iq1s_expect[3]   = { 0xffffffffffffffffULL, 0xffffffffffffff01ULL, 0x0101010101010101ULL };
static const uint64_t iq2xxs_expect[3] = { 0x0808080808080808ULL, 0x080808080808082bULL, 0x2b2b2b1908081908ULL };
static const uint64_t iq2xs_expect[3]  = { 0x0808080808080808ULL, 0x080808080808082bULL, 0x2b2b2b2b2b2b2b2bULL };
static const uint64_t iq2s_expect[3]   = { 0x0808080808080808ULL, 0x080808080808082bULL, 0x2b2b2b2b2b2b2b2bULL };
static const uint32_t iq3xxs_expect[3] = { 0x04040404u, 0x04040414u, 0x3e341c04u };
static const uint32_t iq3s_expect[3]   = { 0x01010101u, 0x01010103u, 0x0f0f0101u };

static int check_grid_u64(const uint64_t * table, const uint64_t * expect, size_t n) {
    int bad = 0;
    if (table[0] != expect[0]) bad++;
    if (table[1] != expect[1]) bad++;
    if (table[n - 1] != expect[2]) bad++;
    return bad;
}

static int check_grid_u32(const uint32_t * table, const uint32_t * expect, size_t n) {
    int bad = 0;
    if (table[0] != expect[0]) bad++;
    if (table[1] != expect[1]) bad++;
    if (table[n - 1] != expect[2]) bad++;
    return bad;
}

int iq_table_spotcheck(void) {
    int bad = 0;

    for (int i = 0; i < 8; i++) {
        if (kmask_iq2xs[i] != (uint8_t)(1u << i)) bad++;
    }
    for (int i = 0; i < 128; i++) {
        if (ksigns_iq2xs[i] != expect_ksigns[i]) bad++;
    }
    for (int i = 0; i < 16; i++) {
        if (kvalues_iq4nl[i] != expect_iq4nl[i]) bad++;
        if (k32_iq4nl_tab[i] != (int32_t)expect_iq4nl[i]) bad++;
        if (kvalues_fp4[i] != expect_fp4[i]) bad++;
        if (k32_nvfp4_values[i] != (float)expect_fp4[i]) bad++;
    }
    for (int i = 0; i < 6; i++) {
        if (iq_pow3[i] != (uint8_t)(i == 0 ? 1 : 3 * iq_pow3[i - 1])) bad++;
    }

    /* the derived sign table must equal the bit-mask expansion, lane by lane */
    for (int i = 0; i < 128; i++) {
        for (int b = 0; b < 8; b++) {
            const int8_t want = (expect_ksigns[i] & (1 << b)) ? -1 : 1;
            if (keven_signs_q2xs[i * 8 + b] != want) bad++;
        }
    }
    /* derived ksigns64 must match the upstream table byte for byte */
    for (int i = 0; i < 128; i++) {
        if (ksigns64_derived[i] != ksigns64[i]) bad++;
    }

    bad += check_grid_u64(iq1s_grid,   iq1s_expect,   2048);
    bad += check_grid_u64(iq2xxs_grid, iq2xxs_expect, 256);
    bad += check_grid_u64(iq2xs_grid,  iq2xs_expect,  512);
    bad += check_grid_u64(iq2s_grid,   iq2s_expect,   1024);
    bad += check_grid_u32(iq3xxs_grid, iq3xxs_expect, 256);
    bad += check_grid_u32(iq3s_grid,   iq3s_expect,   512);

    return bad;
}

